txt=open(Q+'.txt',encoding='utf-8').read()
parts=re.split(r'^### ',txt,flags=re.M)[1:]
P={p.split(' |')[0]:p for p in parts}
assert set(P)==set(L),(set(P)^set(L))
cnt=collections.Counter()
out=open(f'../../returned/batch_14/{Q}.jsonl','w',encoding='utf-8')
for c,(g,r,e,cf) in L.items():
    if g!=0: assert e and e in P[c],(c,e)
    cnt[g]+=1
    out.write(json.dumps({"annotation_code":c,"grade":g,"rationale":r,"evidence_span":e,"confidence":cf,"needs_review":False,"review_note":""},ensure_ascii=False)+"\n")
print(len(L),dict(cnt))
